/* 盤面図（A4 縦。150 dpi で 1240×1754 の px。96 dpi は px の値を 0.64 倍）。盤は局面ごとに 1 枚の SVG（計算式が作る）、持ち駒と見出しは HTML */
.bm-page { box-sizing: border-box; position: relative; padding: 26px 56px 0 !important; background: #fff; color: #111;
  font-family: "Hiragino Mincho ProN", "Yu Mincho", "YuMincho", "MS Mincho", serif; }
.bm-head { text-align: center; height: 64px; }
.bm-title { font-size: 28px; line-height: 36px; font-weight: bold; }
.bm-sub { font-size: 18px; line-height: 26px; color: #333; }
.bm-err, .bm-note { margin: 0 0 8px; padding: 5px 14px; font-size: 18px; line-height: 26px; border-radius: 6px;
  font-family: "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif; }
.bm-err { color: #c00; border: 2px solid #e66; background: #fff5f5; }
.bm-note { color: #555; border: 1.5px solid #bbb; background: #fafafa; }
.bm-grid { display: grid; grid-template-columns: 1fr 1fr; grid-auto-rows: 408px; column-gap: 20px; }
.bm-fig { display: flex; flex-direction: column; align-items: center; }
.bm-hand { width: 344px; height: 22px; font-size: 17px; line-height: 22px; white-space: nowrap; }
.bm-g { text-align: left; }
.bm-s { text-align: right; }
.bm-board { display: block; width: 344px; height: 340px; }
.bm-cap { font-size: 18px; line-height: 24px; font-weight: bold; white-space: nowrap; }
.bm-pn { position: absolute; left: 0; right: 0; bottom: 12px; text-align: center; font-size: 15px; color: #666; }
/* 指定した手数（1 図を大きく。下に指し手の一覧） */
.bm-one .bm-hand { width: 760px; height: 38px; font-size: 26px; line-height: 38px; }
.bm-one .bm-board { width: 760px; height: 752px; }
.bm-one .bm-cap { font-size: 26px; line-height: 40px; }
.bm-memo { margin: 6px 60px 0; padding: 6px 14px; border-left: 4px solid #999; font-size: 19px; line-height: 28px; }
.bm-list { margin: 14px 0 0; display: flex; flex-wrap: wrap; font-size: 16px; line-height: 25px; }
.bm-mv { box-sizing: border-box; width: 141px; padding-right: 4px; white-space: nowrap; overflow: hidden; }
.bm-mv i { display: inline-block; width: 36px; margin-right: 6px; text-align: right; font-style: normal; color: #666; }
.bm-cur { font-weight: bold; background: #ffd966; }
.bm-later { color: #aaa; }
.bm-later i { color: #bbb; }
.bm-bad { color: #c00; font-weight: bold; }

